insert into public.dining_recipes
  (id, name, menu_group, selling_price, serving_yield, serving_unit, is_intermediate, notes, source_file, source_sheet, source_reference, sort_order)
values
  ('d2000000-0000-4000-8000-000000000006', 'かつお水', '中間仕込み', 0, 1000, 'g', true, '掲示板は「水ボトルにかつお出汁ネギスプーン2杯、鶏出汁山盛り1杯、チャーシュー煮汁を満タン」と記載。原価換算用に、かつおだし10g・鶏だし5g・煮汁985g／出来高1,000gで概算登録。ボトル実容量とスプーン重量は要確認。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', '冷たい喜多方ラーメン', 2),
  ('d2000000-0000-4000-8000-000000000007', 'デカ盛り唐揚げ定食', '季節メニュー', 1050, 1, '食', false, '掲示板の唐揚げマニュアルを登録。鶏もも400g、醤油だれ25cc、生姜1杯、ハイミー1杯、片栗粉レンゲ3杯。生姜5g・ハイミー5g・片栗粉45g、付け合わせキャベツ100g・マヨ15g・レモン1/4個は原価換算用の概算。3分40秒揚げる。定食のご飯・味噌汁・青がっぱは既存定食量を適用。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', '唐揚げマニュアル', 70),
  ('d2000000-0000-4000-8000-000000000008', 'デカ盛りモツ炒め定食', '季節メニュー', 1050, 1, '食', false, '掲示板のモツ炒めマニュアルを登録。モツ125g、キャベツ100g、もやし1袋、醤油スープ30ccは記載値。にんにく・人参・玉ねぎ・七味・砂糖・ハイミー・油・小葱は既存店舗レシピの標準量で概算。定食のご飯・味噌汁・青がっぱは既存定食量を適用。モツ単価は要確認。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', 'モツ炒めマニュアル', 71),
  ('d2000000-0000-4000-8000-000000000009', '冷たい喜多方ラーメン', '季節メニュー', 780, 1, '食', false, '掲示板レシピを登録。細麺を3分茹で、ブレンド醤油スープ、生姜、氷、かつお水を使用。具材は細切りチャーシュー、メンマ、小葱、わかめ、ナルト。記載のないg数は既存ラーメンの標準量で概算。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', '冷たい喜多方ラーメン', 72),
  ('d2000000-0000-4000-8000-000000000010', '会津山塩冷やし中華', '季節メニュー', 930, 1, '食', false, '掲示板レシピを登録。塩ラーメンスープ25cc、ガムシロップ1個、ごま油10cc、ワインビネガー10cc、かつお水100cc、マヨネーズ25g。細麺は2分30秒。具材はチャーシュー、メンマ、小ネギ、ワカメ、ナルト、キュウリ、錦糸卵、白ごま。紅しょうが・和からし小袋を添える。未記載の具材量は概算。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', '会津山塩冷し中華', 73),
  ('d2000000-0000-4000-8000-000000000011', 'アスパラタンメン', '季節メニュー', 930, 1, '食', false, '掲示板「会津アスパラと野菜たっぷり山塩タンメン」を登録。ひきチャーシュー20～25g、アスパラ2本、もやし半袋は記載値。ひとつまみ・マドラー・プッシュは既存店舗レシピ標準量で概算。掲示板の旧価格840円ではなく、2026年販売実績930円を採用。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', '会津アスパラと野菜たっぷり山塩タンメン', 74),
  ('d2000000-0000-4000-8000-000000000012', '会津ピーナッツ担々麺', '季節メニュー', 0, 1, '食', false, '掲示板「おくやピーナッツ坦々麺」を登録。味噌35g、ピーナッツ15g、マヨネーズ20g、玉ねぎ40g、ハイミー1g、砂糖2g、ゴマ5g、ラー油10g、ひきチャーシュー40g、角切りチャーシュー30g。麺・スープ・未定量トッピングは原価換算用の概算。公式メニューに販売価格表示がないため価格は未登録。', 'https://v0-line-blush.vercel.app/board/b28f7261-c845-4142-9c41-12b779c8b8bd', '【レシピ】食のブランド館', 'おくやピーナッツ坦々麺', 75),
